/**
 * The planet build's region catalogue: which Geofabrik extracts the world is
 * built from, and how many parts each is built in.
 *
 * `regions.json` beside this file is GENERATED by `scripts/plan-city-regions.ts`
 * from Geofabrik's index and is committed, so what a build compiles is a
 * reviewed list rather than whatever the index says on the day. Regenerate it
 * when Geofabrik's hierarchy changes or the build machine does
 * (`docs/MAP_CITY_PLANET.md` → "Regions").
 */
import catalogue from './regions.json';

/** One region as the catalogue lists it. */
export interface CityRegion {
  /** Geofabrik's download path: `europe/portugal`, `north-america/us/texas`. */
  id: string;
  /** Geofabrik's name for it. */
  name: string;
  /** The extract's size when the catalogue was planned, in bytes. */
  pbfBytes: number;
  /** How many parts it is built in (`ownership.ts` → `splitByDensity`). */
  parts: number;
  /** Official 3D building datasets merged where the compiler supports them (PR #135). */
  official: string[];
}

export interface CityRegionCatalogue {
  generated: string;
  source: string;
  budget: {
    runnerMemoryMb: number;
    usableMemoryMb: number;
    peakMbPerPbfMb: number;
    maxPartBytes: number;
  };
  regions: CityRegion[];
  /** Geofabrik regions deliberately not built, and why (covered by others, or empty). */
  skipped: { id: string; reason: string }[];
}

export const CITY_REGIONS = catalogue as CityRegionCatalogue;

const GEOFABRIK = 'https://download.geofabrik.de';

/** A region id: Geofabrik path segments, lower case. */
export const REGION_ID = /^[a-z0-9-]+(\/[a-z0-9-]+)*$/;

export function extractUrl(id: string): string {
  return `${GEOFABRIK}/${id}-latest.osm.pbf`;
}

export function polyUrl(id: string): string {
  return `${GEOFABRIK}/${id}.poly`;
}

/** The catalogue's entry for a region; throws for one it does not list. */
export function catalogueRegion(id: string, regions = CITY_REGIONS.regions): CityRegion {
  const region = regions.find((candidate) => candidate.id === id);
  if (!region) throw new Error(`${id} is not in citygen/regions.json`);
  return region;
}

/**
 * Select regions for a run: `all`, or a comma-separated list of ids and
 * prefixes (`europe/` selects every European region); an item starting with
 * `-` takes ids or a prefix back out (`all,-europe/spain/madrid`). Unknown
 * names throw, so a typo in a workflow input fails the run instead of
 * building nothing — or everything.
 */
export function selectRegions(selector: string, regions = CITY_REGIONS.regions): CityRegion[] {
  const items = selector
    .split(',')
    .map((item) => item.trim())
    .filter(Boolean);
  const wanted = items.filter((item) => !item.startsWith('-'));
  const unwanted = items.filter((item) => item.startsWith('-')).map((item) => item.slice(1));
  if (wanted.length === 0) throw new Error('no regions selected');
  const match = (item: string) => {
    const found = item.endsWith('/')
      ? regions.filter((region) => region.id.startsWith(item))
      : regions.filter((region) => region.id === item);
    if (found.length === 0) throw new Error(`"${item}" names no region in citygen/regions.json`);
    return found;
  };
  const out = new Set<CityRegion>(wanted.includes('all') ? regions : wanted.flatMap(match));
  for (const item of unwanted) for (const region of match(item)) out.delete(region);
  return regions.filter((region) => out.has(region));
}

/**
 * Pack regions into at most `maxBatches` build jobs, each at most
 * `targetBytes` of extract where possible (a single larger region is a batch
 * of its own). Largest first into the lightest batch, so the jobs finish
 * together. A batch's weight is the extract bytes it downloads and compiles,
 * which is what its time is proportional to (`docs/MAP_CITY_PLANET.md` →
 * "Measured").
 */
export function batchRegions(
  regions: readonly CityRegion[],
  targetBytes: number,
  maxBatches: number,
): CityRegion[][] {
  const total = regions.reduce((sum, region) => sum + region.pbfBytes, 0);
  const count = Math.max(
    1,
    Math.min(maxBatches, regions.length, Math.ceil(total / Math.max(1, targetBytes))),
  );
  const batches: { weight: number; regions: CityRegion[] }[] = Array.from(
    { length: count },
    () => ({
      weight: 0,
      regions: [],
    }),
  );
  for (const region of [...regions].sort(
    (a, b) => b.pbfBytes - a.pbfBytes || a.id.localeCompare(b.id),
  )) {
    let lightest = batches[0];
    for (const batch of batches) if (batch.weight < lightest.weight) lightest = batch;
    lightest.regions.push(region);
    lightest.weight += region.pbfBytes;
  }
  return batches
    .filter((batch) => batch.regions.length > 0)
    .map((batch) => batch.regions.sort((a, b) => a.id.localeCompare(b.id)));
}
